css:
body {
	margin: 0;
	font-family: sans-serif;
}

.page.mk-1twsu9x {
				padding: 24px;
				background: #fbf8f1;
				color: #1f1d1a;
			}
			.form.mk-1twsu9x {
				display: grid;
				gap: 16px;
				padding: 20px;
				border: 1px solid #e4ddcf;
				border-radius: 14px;
				background: #ffffff;
			}
			.field.mk-1twsu9x {
				display: grid;
				gap: 6px;
				font-weight: 600;
			}
			.field input.mk-1twsu9x,
			.field textarea.mk-1twsu9x {
				box-sizing: border-box;
				width: 100%;
				padding: 12px 14px;
				border: 1px solid #e4ddcf;
				background: #fbf8f1;
				font: inherit;
				font-family: Ahem;
				font-weight: 400;
			}
			.field textarea.mk-1twsu9x {
				display: block;
				resize: none;
				scrollbar-width: none;
			}
			.save.mk-1twsu9x {
				display: block;
				padding: 12px 16px;
				border: 0;
				border-radius: 12px;
				background: #2f6f5e;
				color: #ffffff;
				font: inherit;
			}
